"""Journal parsing: text in, transactions out."""

from collections import defaultdict
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path


class JournalError(Exception):
    """A journal that cannot be read or understood."""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: Decimal
    currency: str


@dataclass(frozen=True)
class Transaction:
    date: str
    payee: str
    postings: list[Posting]
    source: str = ""
    line: int = 0

    def residual(self):
        """Per-currency sums that are not zero."""
        totals = defaultdict(Decimal)
        for posting in self.postings:
            totals[posting.currency] += posting.amount
        return {c: a for c, a in totals.items() if a}


def load(path):
    """Read a journal file, following any `include` lines it holds."""
    path = Path(path)
    try:
        text = path.read_text()
    except FileNotFoundError:
        raise JournalError(f"{path}: no such file") from None
    return parse(text, str(path))


def parse(text, source=""):
    transactions = []
    header = None
    entries = []

    def flush():
        if header is not None:
            date, payee, number = header
            transactions.append(
                Transaction(date, payee, _resolve(entries, source), source, number)
            )

    for number, line in enumerate(text.splitlines(), start=1):
        line = line.split(";")[0].rstrip()
        if not line.strip():
            continue
        if line[0].isspace():
            if header is None:
                raise JournalError(
                    f"{source}:{number}: posting outside of a transaction"
                )
            entries.append((number, line.split()))
        elif line.startswith("include "):
            flush()
            header, entries = None, []
            included = Path(source).parent / line.split(" ", 1)[1].strip()
            transactions.extend(load(included))
        else:
            flush()
            date, _, payee = line.partition(" ")
            header, entries = (date, payee.strip(), number), []
    flush()
    return transactions


def _resolve(entries, source):
    """Turn split posting lines into postings, filling in an elided amount."""
    postings = []
    elided = None
    for number, entry in entries:
        if len(entry) == 1:
            elided = entry[0]
            continue
        account, amount, currency = entry
        postings.append(Posting(account, _decimal(amount, source, number), currency))
    if elided is None:
        return postings
    residual = defaultdict(Decimal)
    for posting in postings:
        residual[posting.currency] += posting.amount
    postings.extend(
        Posting(elided, -amount, currency)
        for currency, amount in residual.items()
        if amount
    )
    return postings


def _decimal(text, source, number):
    try:
        return Decimal(text)
    except InvalidOperation:
        raise JournalError(f'{source}:{number}: bad amount: "{text}"') from None
